# !! Change file paths here !!
pathRteHook = "./Appl/GenData/Rte_Hook.h"               # generated by RTE
pathRteHookArti = "./Appl/Source/Rte_Hook_Arti.c"       # generated by this script
pathRteRunnable = "./Appl/Lauterbach/rte_runnable.cmm"  # generated by this script

# !! Change VFB hook prefix filters here !!
and_keywords = ['FUNC','void','RTE_APPL_CODE']
or_keywords = ['Rte_Runnable_','SchM_Schedulable_']
components_keywords = ['EcuM_','ComM_','BswM_','Dcm_','Can_','Fee_','NvM_','Rtm_','Xcp_']

# *********************************************************************************************************************/

def parseCommandLine(pathRteHook, pathRteHookArti, pathRteRunnable):
    desc = '''
Vector VFB Hooks implementation generator python script for timing measurements with Lauterbach TRACE32.
Copyright (c) 2023 Vector Informatik GmbH. All rights reserved.'''
    parser = argparse.ArgumentParser(description = desc, formatter_class=argparse.RawTextHelpFormatter)
    parser.add_argument("--header", dest = "header", default = pathRteHook, metavar="FILE", help = "input: Rte_hook.h file path")
    parser.add_argument("--source", dest = "source", default = pathRteHookArti, metavar="FILE", help = "output: Rte_hook_Arti.c file path")
    parser.add_argument("--script", dest = "script", default = pathRteRunnable, metavar="FILE", help = "output: rte_runnable.cmm file path")
    args = parser.parse_args()
    pathRteHook = args.header
    pathRteHookArti = args.source
    pathRteRunnable = args.script
    return pathRteHook, pathRteHookArti, pathRteRunnable

# Optional calling with command line arguments
pathRteHook, pathRteHookArti, pathRteRunnable = parseCommandLine(pathRteHook, pathRteHookArti, pathRteRunnable)
fsrc=open(pathRteHook,'r')
fdest=open(pathRteHookArti,'w')
cmmdest=open(pathRteRunnable,'w')


def GET_FuncName(str):  # grep the Runnables name, for example ")Runnables_name("
    sLoc=str.find(")")+1
    length=str[sLoc:].find("(")
    return ((str[sLoc:(sLoc+length)]).strip())

def GET_RunnableName(str):
    for keyword in or_keywords:
        if keyword in str:
            start=keyword
            break
    end='_Start('

    for component in components_keywords:
        if component in str:
            strnew = (str.split(start))[1].split(end)[0]
            strsplit = (strnew.split(component,1))
            str = start + strsplit[1] + end

    return ((str.split(start))[1].split(end)[0])

